const crypto = require('crypto');
const input = $input.first().json;
const body = input.body || input;

// Support SAML and OAuth2 callbacks
const ssoData = {
  provider: body.provider || 'oauth2', // saml, oauth2, oidc
  email: body.email || body.nameID || body.user_email,
  name: body.name || body.displayName || '',
  provider_user_id: body.sub || body.user_id || body.nameID,
  groups: body.groups || body.roles || [],
  raw_token: body.access_token || body.id_token || null,
  client_id: body.client_id || body.state
};

if (!ssoData.email) return [{ json: { error: true, status: 401, message: 'SSO authentication failed' } }];

// Generate session token
const sessionToken = crypto.randomBytes(48).toString('hex');
const expiresAt = new Date(Date.now() + 8 * 60 * 60 * 1000); // 8 hours

return [{ json: { ...ssoData, session_token: sessionToken, expires_at: expiresAt.toISOString() } }];

const input = $input.first().json;
const body = input.body || input;
const token = body.token || (input.headers || {})['x-session-token'];
if (!token) return [{ json: { valid: false, message: 'No token provided' } }];
return [{ json: { token, required_role: body.required_role || 'viewer', resource: body.resource || '*' } }];

const session = $input.first().json;
const request = $node['Parse Verify'].json;

if (!session.email) {
  return [{ json: { valid: false, message: 'Invalid or expired session' } }];
}

// Role hierarchy: admin > manager > editor > viewer
const roleHierarchy = { admin: 4, manager: 3, editor: 2, viewer: 1 };
const userLevel = roleHierarchy[session.role] || 1;
const requiredLevel = roleHierarchy[request.required_role] || 1;

const hasAccess = userLevel >= requiredLevel;

// Parse permissions
let permissions = [];
try { permissions = JSON.parse(session.permissions || '[]'); } catch(e) {}

return [{ json: {
  valid: true,
  authorized: hasAccess,
  email: session.email,
  role: session.role,
  client_id: session.client_id,
  permissions: permissions,
  message: hasAccess ? 'Access granted' : `Insufficient permissions. Required: ${request.required_role}, Have: ${session.role}`
}}];
